template:
{# E-Invoice QR Code web template #}
{%- set data = (values.qr_text or "") | trim -%}
{%- if data -%}
  {# Heuristics: treat as base64 if starts with a data URL or looks like PNG/JPEG base64 #}
  {%- set looks_like_data_url = data.startswith('data:image') -%}
  {%- set looks_like_png_b64 = (not looks_like_data_url) and (data[:10] == 'iVBORw0KG') -%}
  {%- set looks_like_jpg_b64 = (not looks_like_data_url) and (data[:7] == '/9j/4AA') -%}
  {% if looks_like_data_url or looks_like_png_b64 or looks_like_jpg_b64 %}
    <img
      src="{{ data if looks_like_data_url else ('data:image/png;base64,' ~ data) }}"
      alt="E-Invoice QR Code"
      style="width:140px; height:140px; object-fit:contain;"
    />
  {% else %}
    {# Treat as raw text -> generate QR via external service #}
    <img
      src="https://quickchart.io/qr?size=140&text={{ data | urlencode }}"
      alt="E-Invoice QR Code"
      style="width:140px; height:140px; object-fit:contain;"
    />
  {% endif %}
{%- else -%}
  <div style="font-size:10px; color:#666;">QR code not available</div>
{%- endif -%}
